<?php
// Shared view; access is enforced by the resident and administration entry points.
if (!isset($messageAdmin,$_SESSION['user_id'])) { http_response_code(404); exit; }
require_once __DIR__ . '/message_inbox_support.php';
require_once __DIR__ . '/report_activity.php';
$prefix=$messageAdmin?'../':'';
$search=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,100):'';
$unreadOnly=($_GET['filter']??'')==='unread';
$inbox=complaintInbox($pdo,(int)$_SESSION['user_id'],$messageAdmin,$search,$unreadOnly,(int)($_GET['page']??1));
$selectedId=isset($_GET['id'])?(int)$_GET['id']:(int)($inbox['items'][0]['id']??0);
$selected=null;
if ($selectedId) {
    [$scope,$scopeParams]=complaintAccessScope();
    $query=$pdo->prepare('SELECT c.*,u.full_name AS resident_name FROM complaints c JOIN users u ON u.id=c.user_id WHERE c.id=? AND '.$scope);
    $query->execute(array_merge([$selectedId],$scopeParams));$selected=$query->fetch(PDO::FETCH_ASSOC);
    if (!$selected) { http_response_code(404); exit('Conversation not found.'); }
}
$parameters=['q'=>$search,'filter'=>$unreadOnly?'unread':'all','page'=>$inbox['page']];
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages — Barangay Mudiang</title><link rel="stylesheet" href="<?php echo $prefix; ?>assets/vendor/bootstrap.min.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><?php include __DIR__.'/ui_theme.php'; ?></head>
<body class="portal-page resident-directory messages-page">
<?php require_once __DIR__.'/portal_navigation.php'; renderPortalNavigation(); ?>
<main class="main"><header class="topbar"><div class="topbar-left"><span class="portal-kicker">Community / Correspondence</span><h1>Messages</h1><p><?php echo $messageAdmin?'Keep every resident conversation moving.':'Stay connected with the team handling your report.'; ?></p></div><div class="topbar-right"><span class="messages-header-count"><strong id="inbox-unread-total"><?php echo $inbox['unread']; ?></strong> unread messages</span></div></header>
<div class="content messages-content"><div class="messages-workspace" data-endpoint="<?php echo $prefix; ?>message_inbox.php" data-selected="<?php echo $selectedId; ?>" data-staff="<?php echo $messageAdmin?'1':'0'; ?>">
<section class="inbox-column" aria-label="Conversation inbox"><div class="inbox-heading"><div><span class="portal-kicker">Your conversations</span><h2>Inbox <span id="inbox-thread-total"><?php echo $inbox['total']; ?></span></h2></div><i class="fas fa-inbox" aria-hidden="true"></i></div><form class="inbox-search" method="get"><label class="visually-hidden" for="inbox-search">Search reports<?php echo $messageAdmin?' or residents':''; ?></label><input type="search" id="inbox-search" name="q" maxlength="100" value="<?php echo conversationEscape($search); ?>" placeholder="<?php echo $messageAdmin?'Search resident, category, report #':'Search category or report #'; ?>"><input type="hidden" name="filter" value="<?php echo $unreadOnly?'unread':'all'; ?>"><button type="submit" aria-label="Search conversations"><i class="fas fa-search" aria-hidden="true"></i></button></form><nav class="inbox-tabs" aria-label="Inbox filter"><a class="<?php echo !$unreadOnly?'active':''; ?>" href="?<?php echo conversationEscape(http_build_query(['q'=>$search,'filter'=>'all'])); ?>" <?php echo !$unreadOnly?'aria-current="page"':''; ?>>All reports</a><a class="<?php echo $unreadOnly?'active':''; ?>" href="?<?php echo conversationEscape(http_build_query(['q'=>$search,'filter'=>'unread'])); ?>" <?php echo $unreadOnly?'aria-current="page"':''; ?>>Unread <span id="inbox-unread-threads"><?php echo $inbox['unread_threads']; ?></span></a></nav><p id="inbox-status" class="inbox-status" role="status">Updates every 15 seconds</p><div id="inbox-list" class="inbox-list">
<?php foreach($inbox['items'] as $thread): ?><a class="inbox-thread <?php echo (int)$thread['id']===$selectedId?'selected':''; ?>" href="?<?php echo conversationEscape(http_build_query($parameters+['id'=>$thread['id']])); ?>" <?php echo (int)$thread['id']===$selectedId?'aria-current="true"':''; ?>><span class="inbox-avatar"><?php echo conversationEscape($messageAdmin?strtoupper(substr($thread['resident_name'],0,1)):'#'); ?></span><span class="inbox-thread-body"><span class="inbox-thread-top"><strong><?php echo conversationEscape($messageAdmin?$thread['resident_name']:$thread['complaint_type']); ?></strong><small><?php echo date('M j',strtotime($thread['last_message_at']??$thread['created_at'])); ?></small></span><span class="inbox-report-label">Report #<?php echo (int)$thread['id']; ?> · <?php echo conversationEscape($thread['complaint_type']); ?></span><span class="inbox-preview"><?php echo conversationEscape($thread['last_body']?:'Start a conversation about this report.'); ?></span><span class="inbox-thread-bottom"><span><?php echo conversationEscape(ucwords(str_replace('_',' ',$thread['status']))); ?></span><?php if($thread['unread']): ?><b><?php echo (int)$thread['unread']; ?> new</b><?php endif; ?></span></span></a><?php endforeach; ?>
<?php if(!$inbox['items']): ?><div class="inbox-empty"><i class="fas fa-inbox" aria-hidden="true"></i><strong><?php echo $unreadOnly?'You’re all caught up.':'No conversations found.'; ?></strong><p><?php echo $search?'Try a different search.':($unreadOnly?'New messages will appear here.':'Conversations become available when a resident submits a report.'); ?></p></div><?php endif; ?></div><nav class="inbox-pagination" aria-label="Inbox pages"><?php if($inbox['page']>1): ?><a href="?<?php echo conversationEscape(http_build_query(array_merge($parameters,['page'=>$inbox['page']-1]))); ?>">Previous</a><?php endif; ?><span>Page <?php echo $inbox['page']; ?> of <?php echo $inbox['pages']; ?></span><?php if($inbox['page']<$inbox['pages']): ?><a href="?<?php echo conversationEscape(http_build_query(array_merge($parameters,['page'=>$inbox['page']+1]))); ?>">Next</a><?php endif; ?></nav></section>
<section class="inbox-reader" aria-label="Selected conversation"><?php if($selected): ?><div class="inbox-case-strip"><div><span class="portal-kicker">Report #<?php echo $selectedId; ?></span><h2><?php echo conversationEscape($selected['complaint_type']); ?></h2><p><?php echo conversationEscape($messageAdmin?$selected['resident_name']:$selected['address']); ?></p></div><div><span class="importance-pill <?php echo conversationEscape($selected['priority']); ?>"><?php echo conversationEscape(ucfirst($selected['priority'])); ?> importance</span><a class="inbox-case-link" href="<?php echo $messageAdmin?'edit_complaint.php':'complaint_conversation.php'; ?>?id=<?php echo $selectedId; ?>">View report <i class="fas fa-arrow-right" aria-hidden="true"></i></a></div></div><?php renderComplaintConversation($selectedId,$messageAdmin,$prefix); if(!$messageAdmin)renderResidentRemarks($pdo,$selectedId); ?><?php else: ?><div class="inbox-reader-empty"><span><i class="fas fa-comments" aria-hidden="true"></i></span><span class="portal-kicker">Every concern deserves a conversation</span><h2>A clearer path to resolution.</h2><p>Select a report to ask questions, share details, and follow up with <?php echo $messageAdmin?'the resident':'your barangay'; ?>.</p><?php if(!$messageAdmin): ?><a class="btn btn-primary" href="submit_complaint_form.php">Submit a concern</a><?php endif; ?></div><?php endif; ?></section>
</div></div></main><script src="<?php echo $prefix; ?>assets/message-inbox.js?v=1" defer></script><?php if($messageAdmin)include __DIR__.'/admin/notification_widget.php'; ?></body></html>
